61	/// Fits a list to the terminal. Inquire redraws relative to the previous frame, so a frame taller than the terminal
62	/// puts the highlight and ticks on the wrong rows. When the size is unknown the page is `wanted` and labels are kept.
63	pub fn fit_list(kind: ListKind, prompt: &str, wanted: usize, labels: &[String]) -> ListLayout {
