67	/// [`fit_list`] on a terminal of `size` (columns, rows).
68	fn fit_list_to(size: Option<(u16, u16)>, kind: ListKind, prompt: &str, wanted: usize, labels: &[String]) -> ListLayout {
69	    let Some((columns, rows)) = size.map(|(columns, rows)| (usize::from(columns).max(1), usize::from(rows))) else {
70	        return ListLayout {
71	            page_size: wanted,
72	            labels: labels.to_vec(),
73	        };
74	    };
75	    let wrapped = |text: &str| UnicodeWidthStr::width(text).div_ceil(columns).max(1);
76	    // `? <prompt> ` then `[<help>]`.
77	    let chrome = wrapped(&format!("? {prompt} ")) + wrapped(&format!("[{}]", kind.help()));
78	    // One row stays free: a frame as tall as the terminal scrolls it.
79	    let room = rows.saturating_sub(chrome + 1).max(1);
80	    let label_width = columns.saturating_sub(kind.prefix()).max(1);
81	    ListLayout {
82	        page_size: wanted.min(room).max(1),
83	        labels: labels.iter().map(|label| truncate(label, label_width)).collect(),
84	    }
85	}
