87	/// `text` cut to `width` columns, ending in `...` when something was cut.
88	fn truncate(text: &str, width: usize) -> String {
89	    if UnicodeWidthStr::width(text) <= width {
90	        return text.to_owned();
91	    }
92	    let ellipsis = width > 3;
93	    let keep = if ellipsis { width - 3 } else { width };
94	    let mut cut = String::new();
95	    let mut used = 0;
96	    for character in text.chars() {
97	        let next = used + UnicodeWidthChar::width(character).unwrap_or(0);
98	        if next > keep {
99	            break;
100	        }
101	        used = next;
102	        cut.push(character);
103	    }
104	    if ellipsis {
105	        cut.push_str("...");
106	    }
107	    cut
108	}
