148	        std::thread::sleep(Duration::from_millis(200));
149	        self.master.write_all(keys.as_bytes()).unwrap();
150	    }
151	
152	    /// Delivers SIGINT to the child itself, as `kill -INT` or a closing terminal would, with no Ctrl-C byte typed.
153	    fn interrupt(&self) {
154	        let status = Command::new("kill")
155	            .args(["-INT", &self.child.id().to_string()])
156	            .status()
157	            .unwrap();
158	        assert!(status.success());
159	    }
160	
161	    /// The terminal is back in line mode with echo, as the shell expects after the child exits.
162	    fn assert_terminal_restored(&self) {
163	        let out = Command::new("stty")
164	            .arg("-a")
165	            .stdin(self.tty.try_clone().unwrap())
166	            .output()
167	            .unwrap();
168	        let settings = String::from_utf8_lossy(&out.stdout);
169	        let flags: Vec<&str> = settings.split(|c: char| c.is_whitespace() || c == ';').collect();
170	        assert!(
171	            flags.contains(&"icanon") && flags.contains(&"echo"),
172	            "the terminal is left raw:\n{settings}"
173	        );
174	    }
175	
176	    fn exit_code(&mut self) -> Option<i32> {
177	        self.status().code()
178	    }
179	
180	    fn status(&mut self) -> ExitStatus {
181	        let deadline = Instant::now() + Duration::from_secs(20);
182	        loop {
183	            if let Some(status) = self.child.try_wait().unwrap() {
184	                std::thread::sleep(Duration::from_millis(200));
185	                return status;
186	            }
187	            assert!(Instant::now() < deadline, "add did not exit:\n{}", self.screen());
188	            std::thread::sleep(Duration::from_millis(20));
189	        }
190	    }
191	}
