202	fn changesets(root: &Path) -> Vec<String> {
203	    std::fs::read_dir(root.join(".changeset"))
204	        .map(|entries| {
205	            entries
206	                .map(|e| e.unwrap().path())
207	                .filter(|path| path.extension().is_some_and(|ext| ext == "md"))
208	                .filter(|path| path.file_name().is_some_and(|name| name != "README.md"))
209	                .map(|path| std::fs::read_to_string(path).unwrap())
210	                .collect()
211	        })
212	        .unwrap_or_default()
213	}
