    #[derive(Default)]
    struct Scripted {
        /// `None` answers as Esc.
        selections: std::collections::VecDeque<Option<Vec<usize>>>,
        summary: Option<Summary>,
        confirm: bool,
        /// Esc at the summary or at the confirmation.
        esc_at_summary: bool,
        esc_at_confirm: bool,
        confirm_asked: bool,
